class InputConnection_RequestTextInputState_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static InputConnection::RequestTextInputStateCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<InputConnection_RequestTextInputState_ProxyToResponder> proxy(
        new InputConnection_RequestTextInputState_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&InputConnection_RequestTextInputState_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~InputConnection_RequestTextInputState_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  InputConnection_RequestTextInputState_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "InputConnection::RequestTextInputStateCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      TextInputStatePtr in_state);
};

bool InputConnection_RequestTextInputState_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::InputConnection_RequestTextInputState_ResponseParams_Data* params =
      reinterpret_cast<
          internal::InputConnection_RequestTextInputState_ResponseParams_Data*>(
              message->mutable_payload());
  
  bool success = true;
  TextInputStatePtr p_state{};
  InputConnection_RequestTextInputState_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadState(&p_state))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        InputConnection::Name_, 3, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run(
std::move(p_state));
  return true;
}

