// static
bool StructTraits<::arc::mojom::ImeInfo::DataView, ::arc::mojom::ImeInfoPtr>::Read(
    ::arc::mojom::ImeInfo::DataView input,
    ::arc::mojom::ImeInfoPtr* output) {
  bool success = true;
  ::arc::mojom::ImeInfoPtr result(::arc::mojom::ImeInfo::New());
  
      if (success && !input.ReadImeId(&result->ime_id))
        success = false;
      if (success && !input.ReadDisplayName(&result->display_name))
        success = false;
      if (success)
        result->enabled = input.enabled();
      if (success && !input.ReadSettingsUrl(&result->settings_url))
        success = false;
      if (success)
        result->is_allowed_in_clamshell_mode = input.is_allowed_in_clamshell_mode();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::arc::mojom::TextInputState::DataView, ::arc::mojom::TextInputStatePtr>::Read(
    ::arc::mojom::TextInputState::DataView input,
    ::arc::mojom::TextInputStatePtr* output) {
  bool success = true;
  ::arc::mojom::TextInputStatePtr result(::arc::mojom::TextInputState::New());
  
      if (success)
        result->cursor_pos = input.cursor_pos();
      if (success && !input.ReadText(&result->text))
        success = false;
      if (success && !input.ReadTextRange(&result->text_range))
        success = false;
      if (success && !input.ReadSelectionRange(&result->selection_range))
        success = false;
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success)
        result->should_do_learning = input.should_do_learning();
      if (success)
        result->flags = input.flags();
      if (success)
        result->first_update_after_operation = input.first_update_after_operation();
      if (success && !input.ReadCompositionTextRange(&result->composition_text_range))
        success = false;
  *output = std::move(result);
  return success;
}

